local({
  mother <- as.numeric(P22a)
  father <- as.numeric(P23a)
  case_when(
    mother %in% 1 | father %in% 1 ~ "Non-minority",
    mother %in% 2 & (father %in% 2 | is.na(father)) ~ "Minority",
    father %in% 2 & is.na(mother) ~ "Minority",
    .default = "Unknown"
  )
})

local({
  maths <- if_else(as.numeric(P24) %in% 1:5, as.numeric(P24), NA_real_)
  portuguese <- if_else(as.numeric(P25) %in% 1:5, as.numeric(P25), NA_real_)
  if_else(as.numeric(P27) %in% 1, NA_real_, (maths + portuguese) / 2)
})
